Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-tolowercase":{"key":"topic-tolowercase","number":null,"title":"To Lower Case","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"To Lower Case.py","code":"class Solution:\n    def toLowerCase(self, s: str) -> str:\n        isUpper = lambda x: 'A' <= x <= 'Z'\n        toLower = lambda x: chr(ord(x) | 32)\n        return ''.join([toLower(x) if isUpper(x) else x for x in s])","hash":"8f0959bc04a2703300d592d30cd202d2d3fc2b0f912fac5798fb49390ebc3d33","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-05 Leetcoding Challenge/To Lower Case.py"}]}],"sources":["solutions"]},"topic-topkfrequenctelements":{"key":"topic-topkfrequenctelements","number":null,"title":"Top K Frequenct Elements","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Top K Frequenct Elements.py","code":"class Solution:\n    def topKFrequent(self, nums: List[int], k: int) -> List[int]:\n        count = Counter(nums)\n        numbers = list(count.keys())\n        \n        def partition(left, right, pivotIndex):\n            pivotFrequency = count[numbers[pivotIndex]]\n            numbers[pivotIndex], numbers[right] = numbers[right], numbers[pivotIndex]\n            index = left\n            for i in range(left, right):\n                if count[numbers[i]] < pivotFrequency:\n                    numbers[index], numbers[i] = numbers[i], numbers[index]\n                    index += 1\n            numbers[index], numbers[right] = numbers[right], numbers[index]\n            return index\n        \n        def quickSelect(left, right, kSmallest):\n            if left == right:\n                return\n            pivotIndex = partition(left, right, random.randint(left, right))\n            if kSmallest == pivotIndex:\n                return\n            elif kSmallest < pivotIndex:\n                quickSelect(left, pivotIndex - 1, kSmallest)\n            else:\n                quickSelect(pivotIndex + 1, right, kSmallest)\n        \n        numbersLen = len(numbers)\n        quickSelect(0, numbersLen - 1, numbersLen - k)\n        return numbers[numbersLen - k:]","hash":"21d042c9121e4f2a77ea6763e4f59ae8ca9610eacd7c6286ba8d90981c2f308b","origins":[{"source":"solutions","path":"Hash Table/Top K Frequenct Elements.py"}]}],"sources":["solutions"]},"topic-tossstrangecoins":{"key":"topic-tossstrangecoins","number":null,"title":"Toss Strange Coins","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Toss Strange Coins.py","code":"class Solution:\n    def probabilityOfHeads(self, prob: List[float], target: int) -> float:\n        # dp[p][k] = probability of obtaining k heads for first p coins\n        dp = [[0] * (target + 1) for _ in range(len(prob) + 1)]\n        dp[0][0] = 1\n        for p in range(1, len(prob) + 1):\n            dp[p][0] = dp[p - 1][0] * (1 - prob[p - 1])\n        for k in range(1, target + 1):\n            for p in range(k, len(prob) + 1):\n                dp[p][k] = (dp[p - 1][k] * (1 - prob[p - 1])) + (dp[p - 1][k - 1] * prob[p - 1])\n        return dp[-1][-1]","hash":"034fd4db30b37be259e8580e1abcedf79f792f1dda99f310f32fed24a83afd83","origins":[{"source":"solutions","path":"Toss Strange Coins.py"}]}],"sources":["solutions"]},"topic-trafficlightcontrolledintersection":{"key":"topic-trafficlightcontrolledintersection","number":null,"title":"Traffic Light Controlled Intersection","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Traffic Light Controlled Intersection.py","code":"from threading import Lock\n\nclass TrafficLight:\n    def __init__(self):\n        self.lock = Lock()\n        self.greenLightOn = 1\n\n    def carArrived(\n        self,\n        carId: int,                      # ID of the car\n        roadId: int,                     # ID of the road the car travels on. Can be 1 (road A) or 2 (road B)\n        direction: int,                  # Direction of the car\n        turnGreen: 'Callable[[], None]', # Use turnGreen() to turn light to green on current road\n        crossCar: 'Callable[[], None]'   # Use crossCar() to make car cross the intersection\n    ) -> None:\n        self.lock.acquire()\n        if self.greenLightOn == roadId:\n            crossCar()\n        else:\n            turnGreen()\n            self.greenLightOn = roadId\n            crossCar()\n        self.lock.release()","hash":"e2e65ceacdd5693b93671a4354448d50cf2e85d746de14c05af633719c07ee90","origins":[{"source":"solutions","path":"Traffic Light Controlled Intersection.py"}]}],"sources":["solutions"]},"topic-transposematrix":{"key":"topic-transposematrix","number":null,"title":"Transpose Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Transpose Matrix.py","code":"class Solution:\n    def transpose(self, matrix: List[List[int]]) -> List[List[int]]:\n        result = [[0] * len(matrix) for _ in range(len(matrix[0]))]\n        for i in range(len(matrix)):\n            for j in range(len(matrix[0])):\n                result[j][i] = matrix[i][j]\n        return result","hash":"9f4a241104dfa7c4ca8a0968828c8bdccef06968114fc44d44fdca988384fca9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-06 Leetcoding Challenge/Transpose Matrix.py"}]},{"language":"python","name":"Transpose Matrix.py","code":"class Solution:\n    def transpose(self, A: List[List[int]]) -> List[List[int]]:\n        B = [[0] * len(A) for _ in range(len(A[0]))]\n        for i in range(len(A)):\n            for j in range(len(A[0])):\n                B[j][i] = A[i][j]\n        return B","hash":"53de56aacf1d67c4f1c8f8ec1bcd79293ffc055153b50abd81ed2b57959e63c8","origins":[{"source":"solutions","path":"Transpose Matrix.py"}]}],"sources":["solutions"]},"algorithm-trie":{"key":"algorithm-trie","number":null,"title":"trie","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"trie.py","code":"\"\"\"\nA Trie/Prefix Tree is a kind of search tree used to provide quick lookup\nof words/patterns in a set of words. A basic Trie however has O(n^2) space complexity\nmaking it impractical in practice. It however provides O(max(search_string, length of\nlongest word)) lookup time making it an optimal approach when space is not an issue.\n\"\"\"\n\n\nclass TrieNode:\n    def __init__(self) -> None:\n        self.nodes: dict[str, TrieNode] = {}  # Mapping from char to TrieNode\n        self.is_leaf = False\n\n    def insert_many(self, words: list[str]) -> None:\n        \"\"\"\n        Inserts a list of words into the Trie\n        :param words: list of string words\n        :return: None\n        \"\"\"\n        for word in words:\n            self.insert(word)\n\n    def insert(self, word: str) -> None:\n        \"\"\"\n        Inserts a word into the Trie\n        :param word: word to be inserted\n        :return: None\n        \"\"\"\n        curr = self\n        for char in word:\n            if char not in curr.nodes:\n                curr.nodes[char] = TrieNode()\n            curr = curr.nodes[char]\n        curr.is_leaf = True\n\n    def find(self, word: str) -> bool:\n        \"\"\"\n        Tries to find word in a Trie\n        :param word: word to look for\n        :return: Returns True if word is found, False otherwise\n        \"\"\"\n        curr = self\n        for char in word:\n            if char not in curr.nodes:\n                return False\n            curr = curr.nodes[char]\n        return curr.is_leaf\n\n    def delete(self, word: str) -> None:\n        \"\"\"\n        Deletes a word in a Trie\n        :param word: word to delete\n        :return: None\n        \"\"\"\n\n        def _delete(curr: TrieNode, word: str, index: int) -> bool:\n            if index == len(word):\n                # If word does not exist\n                if not curr.is_leaf:\n                    return False\n                curr.is_leaf = False\n                return len(curr.nodes) == 0\n            char = word[index]\n            char_node = curr.nodes.get(char)\n            # If char not in current trie node\n            if not char_node:\n                return False\n            # Flag to check if node can be deleted\n            delete_curr = _delete(char_node, word, index + 1)\n            if delete_curr:\n                del curr.nodes[char]\n                return len(curr.nodes) == 0\n            return delete_curr\n\n        _delete(self, word, 0)\n\n\ndef print_words(node: TrieNode, word: str) -> None:\n    \"\"\"\n    Prints all the words in a Trie\n    :param node: root node of Trie\n    :param word: Word variable should be empty at start\n    :return: None\n    \"\"\"\n    if node.is_leaf:\n        print(word, end=\" \")\n\n    for key, value in node.nodes.items():\n        print_words(value, word + key)\n\n\ndef test_trie() -> bool:\n    words = \"banana bananas bandana band apple all beast\".split()\n    root = TrieNode()\n    root.insert_many(words)\n    # print_words(root, \"\")\n    assert all(root.find(word) for word in words)\n    assert root.find(\"banana\")\n    assert not root.find(\"bandanas\")\n    assert not root.find(\"apps\")\n    assert root.find(\"apple\")\n    assert root.find(\"all\")\n    root.delete(\"all\")\n    assert not root.find(\"all\")\n    root.delete(\"banana\")\n    assert not root.find(\"banana\")\n    assert root.find(\"bananas\")\n    return True\n\n\ndef print_results(msg: str, passes: bool) -> None:\n    print(str(msg), \"works!\" if passes else \"doesn't work :(\")\n\n\ndef pytests() -> None:\n    assert test_trie()\n\n\ndef main() -> None:\n    \"\"\"\n    >>> pytests()\n    \"\"\"\n    print_results(\"Testing trie functionality\", test_trie())\n\n\nif __name__ == \"__main__\":\n    main()\n","hash":"8f7fde5b1448a2a4567285c1b91627371264df9fa6380c2f4bd74ea1e0dba2dc","origins":[{"source":"algorithms","path":"data_structures/trie/trie.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/data_structures/trie/trie.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-trimabinarysearchtree":{"key":"topic-trimabinarysearchtree","number":null,"title":"Trim a Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Trim a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def trimBST(self, root: TreeNode, low: int, high: int) -> TreeNode:\n        def trim(node):\n            if not node:\n                return None\n            elif node.val < low:\n                return trim(node.right)\n            elif node.val > high:\n                return trim(node.left)\n            else:\n                node.left = trim(node.left)\n                node.right = trim(node.right)\n                return node\n        return trim(root)","hash":"a430ce51b891fa038e904273e99e36421dd430c31412708d311f94348207e0da","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Trim a Binary Search Tree.py"}]},{"language":"python","name":"Trim a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def trimBST(self, root: Optional[TreeNode], L: int, R: int) -> Optional[TreeNode]:\n        def trim(node):\n            if not node:\n                return None\n            elif node.val > R:\n                return trim(node.left)\n            elif node.val < L:\n                return trim(node.right)\n            else:\n                node.left = trim(node.left)\n                node.right = trim(node.right)\n                return node\n        return trim(root)","hash":"33a777c83c4b1b2ee6873682dd3be77b7c0add43878f7652fa0df4f482c4adcb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Trim a Binary Search Tree.py"}]},{"language":"python","name":"Trim a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def trimBST(self, root: TreeNode, L: int, R: int) -> TreeNode:\n        def trim(node):\n            if not node:\n                return None\n            elif node.val > R:\n                return trim(node.left)\n            elif node.val < L:\n                return trim(node.right)\n            else:\n                node.left = trim(node.left)\n                node.right = trim(node.right)\n                return node\n        return trim(root)","hash":"35d1b50a61b680ef5113a78cfd41dee2829bb37fef702cb25ecfa8c4c6d3c316","origins":[{"source":"solutions","path":"Trim a Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-tweetcountsperfrequency":{"key":"topic-tweetcountsperfrequency","number":null,"title":"Tweet Counts Per Frequency","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Tweet Counts Per Frequency.py","code":"class TweetCounts:\n\n    def __init__(self):\n        self.recordsMap = defaultdict(list)\n        self.recordsSortedMap = defaultdict(bool)\n        self.freqMap = {\n            \"minute\": 60,\n            \"hour\": 3600,\n            \"day\": 86400\n        }\n\n    def recordTweet(self, tweetName: str, time: int) -> None:\n        self.recordsMap[tweetName].append(time)\n        self.recordsSortedMap[tweetName] = False\n\n    def getTweetCountsPerFrequency(self, freq: str, tweetName: str, startTime: int, endTime: int) -> List[int]:\n        delta, tweetTimes, isTweetTimesSorted, start, result = self.freqMap[freq], self.recordsMap[tweetName], self.recordsSortedMap[tweetName], startTime, []\n        if not isTweetTimesSorted:\n            tweetTimes = sorted(tweetTimes)\n            self.recordsMap[tweetName] = tweetTimes\n            self.recordsSortedMap[tweetName] = True\n        while start <= endTime:\n            end = min(start + delta, endTime + 1)\n            result.append(bisect.bisect_left(tweetTimes, end) - bisect.bisect_left(tweetTimes, start))\n            start += delta\n        return result\n\n# Your TweetCounts object will be instantiated and called as such:\n# obj = TweetCounts()\n# obj.recordTweet(tweetName,time)\n# param_2 = obj.getTweetCountsPerFrequency(freq,tweetName,startTime,endTime)","hash":"ed9a1c2584c4cc64563e198590de2429798aa1302fd9c8a53d9968729d69d05f","origins":[{"source":"solutions","path":"Tweet Counts Per Frequency.py"}]}],"sources":["solutions"]},"topic-twocityscheduling":{"key":"topic-twocityscheduling","number":null,"title":"Two City Scheduling","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Two City Scheduling.py","code":"class Solution:\n    def twoCitySchedCost(self, costs: List[List[int]]) -> int:\n        costs, L = sorted(costs, key = lambda a: a[0] - a[1]), len(costs) // 2\n        return sum(c[0] for c in costs[:L]) + sum(c[1] for c in costs[L:])","hash":"5e1701452d33b8c0c8a464cd382773736a26c5388f0f2bb6df58b374de5ff06d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Two City Scheduling.py"}]}],"sources":["solutions"]},"topic-twofurthesthouseswithdifferentcolors":{"key":"topic-twofurthesthouseswithdifferentcolors","number":null,"title":"Two Furthest Houses With Different Colors","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Two Furthest Houses With Different Colors.py","code":"class Solution:\n    def maxDistance(self, colors: List[int]) -> int:\n        left, right = 0, len(colors) - 1\n        while colors[0] == colors[right]:\n            right -= 1\n        while colors[-1] == colors[left]:\n            left += 1\n        return max(len(colors) - 1 - left, right)","hash":"a4fb6fa93015e81397a26a5f3996b296403912b4aed1394c5801b837fe2b2dac","origins":[{"source":"solutions","path":"Two Furthest Houses With Different Colors.py"}]}],"sources":["solutions"]},"topic-twooutofthree":{"key":"topic-twooutofthree","number":null,"title":"Two Out of Three","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Two Out of Three.py","code":"class Solution:\n    def twoOutOfThree(self, nums1: List[int], nums2: List[int], nums3: List[int]) -> List[int]:\n        hashSet1, hashSet2, hashSet3 = set(nums1), set(nums2), set(nums3)\n        freqMap = Counter(hashSet1) + Counter(hashSet2) + Counter(hashSet3)\n        return [num for num, freq in freqMap.items() if freq > 1]","hash":"7a4c9eea37f9484ee3df68f7ca904461d29e9b66f23521032dc2c85876da6166","origins":[{"source":"solutions","path":"Two Out of Three.py"}]}],"sources":["solutions"]},"topic-twosumiiinputarrayissorted":{"key":"topic-twosumiiinputarrayissorted","number":null,"title":"Two Sum II Input Array is sorted","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Two Sum II - Input Array is sorted.py","code":"class Solution:\n    def twoSum(self, numbers: List[int], target: int) -> List[int]:\n        low = 0\n        high = len(numbers) - 1\n        while low < high:\n            currentSum = numbers[low] + numbers[high]\n            if currentSum == target:\n                return [low + 1, high + 1]\n            elif currentSum < target:\n                low += 1\n            else:\n                high -= 1\n        return [-1, -1]","hash":"b81cd079a79b16e380589d09742573d121f16b814be5d3c732c209e30ebb63de","origins":[{"source":"solutions","path":"Google Interview Questions/Two Sum II - Input Array is sorted.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-06 Leetcoding Challenge/Two Sum II - Input Array Is Sorted.py"}]}],"sources":["solutions"]},"topic-twosumlessthank":{"key":"topic-twosumlessthank","number":null,"title":"Two Sum Less Than K","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Two Sum Less Than K.py","code":"class Solution:\n    def twoSumLessThanK(self, A: List[int], K: int) -> int:\n        A.sort()\n        result = -1\n        for i in range(len(A)):\n            j = bisect.bisect_left(A, K - A[i], i + 1) - 1\n            if j > i:\n                result = max(result, A[i] + A[j])\n        return result","hash":"9042cceb1d73aaf10da5097d5f33fcb58f14c9da46aacacfb08c6861d0a4f373","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Two Sum Less Than K.py"}]}],"sources":["solutions"]},"topic-uglynumber":{"key":"topic-uglynumber","number":null,"title":"Ugly Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Ugly Number.py","code":"class Solution:\n    def isUgly(self, num: int) -> bool:\n        for i in (2, 3, 5):\n            while num % i == 0 and num > 1:\n                num //= i\n        return num == 1","hash":"75fffcbcf387b7426abf9cb83d5e43c11a570527e7459f1da3c6ef646c42eeda","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-11 Leetcoding Challenge/Ugly Number.py"},{"source":"solutions","path":"Ugly Number.py"}]}],"sources":["solutions"]},"topic-uglynumberii":{"key":"topic-uglynumberii","number":null,"title":"Ugly Number II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Ugly Number II.py","code":"class Ugly:\n    def __init__(self):\n        self.nums = nums = [1,]\n        i2, i3, i5 = 0, 0, 0\n        for _ in range(1, 1690):\n            ugly = min(nums[i2] * 2, nums[i3] * 3, nums[i5] * 5)\n            nums.append(ugly)\n            if ugly == nums[i2] * 2:\n                i2 += 1\n            if ugly == nums[i3] * 3:\n                i3 += 1\n            if ugly == nums[i5] * 5:\n                i5 += 1\n\nclass Solution:\n    ugly = Ugly()\n    def nthUglyNumber(self, n: int) -> int:\n        return self.ugly.nums[n - 1]","hash":"0b8ce9ab49400174b14536bd384ebd3b0d1b33af6464398f6efa310ca7ea6730","origins":[{"source":"solutions","path":"Ugly Number II.py"}]}],"sources":["solutions"]},"topic-uncommonwordsfromtwosentences":{"key":"topic-uncommonwordsfromtwosentences","number":null,"title":"Uncommon Words from Two Sentences","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Uncommon Words from Two Sentences.py","code":"class Solution:\n    def uncommonFromSentences(self, A: str, B: str) -> List[str]:\n        freqMapA, freqMapB, result = defaultdict(int), defaultdict(int), []\n        for word in A.split():\n            freqMapA[word] += 1\n        for word in B.split():\n            freqMapB[word] += 1\n        for word, frequency in freqMapA.items():\n            if frequency == 1 and word not in freqMapB:\n                result.append(word)\n        for word, frequency in freqMapB.items():\n            if frequency == 1 and word not in freqMapA:\n                result.append(word)\n        return result","hash":"723befc0affa42881afc3b4430b08d95c71c605f088e4a2f8785293ce6bd3b19","origins":[{"source":"solutions","path":"Uncommon Words from Two Sentences.py"}]}],"sources":["solutions"]},"topic-uniqueemailaddresses":{"key":"topic-uniqueemailaddresses","number":null,"title":"Unique Email Addresses","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Unique Email Addresses.py","code":"class Solution:\n    def numUniqueEmails(self, emails: List[str]) -> int:\n        def formatEmail(email):\n            emailParts = email.split('@')\n            emailParts[0] = emailParts[0].replace('.', '')\n            return emailParts[0].split('+')[0] + '@' + emailParts[1]\n        emailsSet = set()\n        for email in emails:\n            emailsSet.add(formatEmail(email))\n        return len(emailsSet)","hash":"7d71061a44c7e9df498db0869f09014846c06c0f41a9cdb51c3a19c794392e0f","origins":[{"source":"solutions","path":"Mock Interviews/Google/Online Assessment 05/Unique Email Addresses.py"}]},{"language":"python","name":"Unique Email Addresses.py","code":"class Solution:\n    def getFormattedEMail(self, email):\n        userName, domain = email.split('@')\n        if '+' in userName:\n            userName = userName.split('+')[0]\n        if '.' in userName:\n            userName = ''.join(userName.split('.'))\n        return userName + '@' + domain\n    \n    def numUniqueEmails(self, emails: List[str]) -> int:\n        emailsSet = set()\n        for email in emails:\n            emailsSet.add(self.getFormattedEMail(email))\n        return len(emailsSet)","hash":"2f68e141829d086e89b89b63e6ed7cd14b9e9780d317d5f251d886cb754f8048","origins":[{"source":"solutions","path":"Unique Email Addresses.py"}]}],"sources":["solutions"]},"topic-univaluedbinarytree":{"key":"topic-univaluedbinarytree","number":null,"title":"Univalued Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Univalued Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isUnivalTree(self, root: Optional[TreeNode]) -> bool:\n        def helper(node, val):\n            if node is None:\n                return True\n            if node.val != val:\n                return False\n            return helper(node.left, val) and helper(node.right, val)\n        return helper(root, root.val)","hash":"5e2f72c98cfde26be2a59eb7e93ca35147b1585b7261a2388e7a4b3a752ee93e","origins":[{"source":"solutions","path":"Univalued Binary Tree.py"}]}],"sources":["solutions"]},"topic-validmountainarray":{"key":"topic-validmountainarray","number":null,"title":"Valid Mountain Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Mountain Array.py","code":"class Solution:\n    def validMountainArray(self, A: List[int]) -> bool:\n        arrayLength = len(A)\n        i = 0\n        while i + 1 < arrayLength and A[i] < A[i + 1]:\n            i += 1\n        if i == 0 or i == arrayLength - 1:\n            return False\n        while i + 1 < arrayLength and A[i] > A[i + 1]:\n            i += 1\n        return i == arrayLength - 1","hash":"34bcf864bc8ddd6f8185e652b3b2b4477a02381614b078fe8b0f1baaa867bf91","origins":[{"source":"solutions","path":"Arrays/Valid Mountain Array.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-12 Leetcoding Challenge/Valid Mountain Array.py"},{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 01/Valid Mountain Array.py"}]},{"language":"python","name":"Valid Mountain Array.py","code":"class Solution:\n    def validMountainArray(self, arr: List[int]) -> bool:\n        arrayLength = len(arr)\n        i = 0\n        while i + 1 < arrayLength and arr[i] < arr[i + 1]:\n            i += 1\n        if i == 0 or i == arrayLength - 1:\n            return False\n        while i + 1 < arrayLength and arr[i] > arr[i + 1]:\n            i += 1\n        return i == arrayLength - 1","hash":"599ff23983f75f356e2f70dead6641958aded89f3703462c0a1c158c5575149d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Valid Mountain Array.py"}]}],"sources":["solutions"]},"topic-validpalindrome":{"key":"topic-validpalindrome","number":null,"title":"Valid Palindrome","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Palindrome.py","code":"class Solution:\n    def isPalindrome(self, s: str) -> bool:\n        s = ''.join(filter(str.isalnum, s.lower()))\n        return s == ''.join(list(reversed(s)))","hash":"302083f12554f77555d6c129718b10a8c1252cd1c2cd61905207760e8821a2b1","origins":[{"source":"solutions","path":"Microsoft Interview Questions/Valid Palindrome.py"}]}],"sources":["solutions"]},"topic-validpalindrome01":{"key":"topic-validpalindrome01","number":null,"title":"Valid Palindrome 01","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Palindrome - 01.py","code":"class Solution:\n    def isPalindrome(self, s: str) -> bool:\n        formattedString = ''.join([c.lower() for c in s if c.isalnum()])\n        if formattedString == formattedString[::-1]:\n            return True\n        return False","hash":"2d10f72748595f64c40426be56a251631fd8c284c932d98ba76209a9cc93e2d4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Valid Palindrome - 01.py"}]}],"sources":["solutions"]},"topic-validpalindrome02":{"key":"topic-validpalindrome02","number":null,"title":"Valid Palindrome 02","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Palindrome - 02.py","code":"class Solution:\n    def isPalindrome(self, s: str) -> bool:\n        s = ''.join(filter(str.isalnum, s.lower()))\n        return s == ''.join(list(reversed(s)))","hash":"302083f12554f77555d6c129718b10a8c1252cd1c2cd61905207760e8821a2b1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Valid Palindrome - 02.py"}]}],"sources":["solutions"]},"topic-validpalindromeii":{"key":"topic-validpalindromeii","number":null,"title":"Valid Palindrome II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Palindrome II.py","code":"class Solution:\n    def validPalindrome(self, s: str) -> bool:\n        def isPalindrome(i, j) -> bool:\n            while i < j:\n                if s[i] != s[j]:\n                    return False\n                i, j = i + 1, j - 1\n            return True\n        i, j = 0, len(s) - 1\n        while i < j:\n            if s[i] != s[j]:\n                return isPalindrome(i, j - 1) or isPalindrome(i + 1, j)\n            i, j = i + 1, j - 1\n        return True","hash":"4e4011589b92f0e525cab144f82cd074d90a55519bb57f5ab484b0afe416490b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Valid Palindrome II.py"}]}],"sources":["solutions"]},"topic-validperfectsquare":{"key":"topic-validperfectsquare","number":null,"title":"Valid Perfect Square","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Perfect Square.py","code":"class Solution:\n    def isPerfectSquare(self, num: int) -> bool:\n        if num < 2:\n            return True\n        left, right = 2, num\n        while left <= right:\n            mid = left + ((right - left) >> 1)\n            n = mid * mid\n            if n == num:\n                return True\n            elif n > num:\n                right = mid - 1\n            else:\n                left = mid + 1\n        return False","hash":"394b0ca9ef4b95d53b5b2a172f6e7b6c2ce249812464cc8b7aaafac0775f0782","origins":[{"source":"solutions","path":"Valid Perfect Square.py"}]}],"sources":["solutions"]},"topic-validsquare":{"key":"topic-validsquare","number":null,"title":"Valid Square","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Square.py","code":"class Solution:\n    def validSquare(self, p1: List[int], p2: List[int], p3: List[int], p4: List[int]) -> bool:\n        lenMap = defaultdict(int)\n        def getDistanceSquare(p1, p2):\n            return (p2[0] - p1[0]) ** 2 + (p2[1] - p1[1]) ** 2\n        lenMap[getDistanceSquare(p1, p2)] += 1\n        lenMap[getDistanceSquare(p2, p3)] += 1\n        lenMap[getDistanceSquare(p3, p4)] += 1\n        lenMap[getDistanceSquare(p4, p1)] += 1\n        lenMap[getDistanceSquare(p1, p3)] += 1\n        lenMap[getDistanceSquare(p2, p4)] += 1\n        return len(lenMap) == 2 and set(lenMap.values()) == set([2, 4])","hash":"ac016d1f05dbf919c9b53a13935071738abc9a01f9bb9f3c5ac7001072aa6aa0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Valid Square.py"}]}],"sources":["solutions"]},"topic-validtictactoestate":{"key":"topic-validtictactoestate","number":null,"title":"Valid Tic Tac Toe State","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Tic-Tac-Toe State.py","code":"class Solution:\n    def validTicTacToe(self, board: List[str]) -> bool:\n        player1, player2, xCount, oCount = 'X', 'O', 0, 0\n        for row in board:\n            for val in row:\n                if val == player1:\n                    xCount += 1\n                if val == player2:\n                    oCount += 1\n        \n        def checkWin(player):\n            nonlocal board\n            for i in range(3):\n                if all(board[i][j] == player for j in range(3)):\n                    return True\n                if all(board[j][i] == player for j in range(3)):\n                    return True\n            return (player == board[0][0] == board[1][1] == board[2][2]) or (player == board[0][2] == board[1][1] == board[2][0])\n        \n        if oCount not in {xCount, xCount - 1}:\n            return False\n        if checkWin(player1) and xCount != oCount + 1:\n            return False\n        if checkWin(player2) and xCount != oCount:\n            return False\n        return True","hash":"1f798b461fd44d952180014eef66c9333f6832931f198b7c36d6d76b6dc993d2","origins":[{"source":"solutions","path":"Valid Tic-Tac-Toe State.py"}]}],"sources":["solutions"]},"topic-validtrianglenumber":{"key":"topic-validtrianglenumber","number":null,"title":"Valid Triangle Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Valid Triangle Number.py","code":"class Solution:\n    def triangleNumber(self, nums: List[int]) -> int:\n        nums.sort()\n        result = 0\n        for i in range(len(nums) - 2):\n            if nums[i] != 0:\n                k = i + 2\n                for j in range(i + 1, len(nums) - 1):\n                    while k < len(nums) and nums[i] + nums[j] > nums[k]:\n                        k += 1\n                    result += k - j - 1\n        return result","hash":"8e0f85c48c56428cb8c743713a576b3eb5d9a81619a495961fb2e60050733f72","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Valid Triangle Number.py"},{"source":"solutions","path":"Valid Triangle Number.py"}]}],"sources":["solutions"]},"topic-validatebinarysearchtreeiterative":{"key":"topic-validatebinarysearchtreeiterative","number":null,"title":"Validate Binary Search Tree Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Validate Binary Search Tree - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isValidBST(self, root: TreeNode) -> bool:\n        stack, inorder = deque(), float('-inf')\n        currentNode = root\n        while currentNode or stack:\n            while currentNode:\n                stack.append(currentNode)\n                currentNode = currentNode.left\n            currentNode = stack.pop()\n            if currentNode.val <= inorder:\n                return False\n            inorder = currentNode.val\n            currentNode = currentNode.right\n        return True","hash":"e977108245dcc578df5c239f30d093b9d40c0b07a92cfe311ab8d0ace6a31f85","origins":[{"source":"solutions","path":"Binary Search Tree/Validate Binary Search Tree - Iterative.py"}]}],"sources":["solutions"]},"topic-validatebinarysearchtreerecursive":{"key":"topic-validatebinarysearchtreerecursive","number":null,"title":"Validate Binary Search Tree Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Validate Binary Search Tree - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isValidBST(self, root: TreeNode) -> bool:\n        def helper(node, lower = float('-inf'), upper = float('inf')):\n            if node is None:\n                return True\n            val = node.val\n            if val <= lower or val >= upper:\n                return False\n            if not helper(node.right, val, upper):\n                return False\n            if not helper(node.left, lower, val):\n                return False\n            return True\n        return helper(root)","hash":"0fea7f950592a434e17bc4bd964699f77cf7ad04856a8fcd8bf125888060d402","origins":[{"source":"solutions","path":"Binary Search Tree/Validate Binary Search Tree - Recursive.py"}]}],"sources":["solutions"]},"topic-validateipaddress":{"key":"topic-validateipaddress","number":null,"title":"Validate IP Address","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Validate IP Address.py","code":"class Solution:\n    def validIPAddress(self, IP: str) -> str:\n        def validateIPv4(IP):\n            parts = IP.split('.')\n            for part in parts:\n                if len(part) not in [1, 2, 3]:\n                    return 'Neither'\n                if part[0] == '0' and len(part) != 1 or not part.isdigit() or int(part) > 255:\n                    return 'Neither'\n            return 'IPv4'\n        def validateIPv6(IP):\n            parts = IP.split(':')\n            hexDigits = '0123456789abcdefABCDEF'\n            for part in parts:\n                if len(part) not in [1, 2, 3, 4] or not all(c in hexDigits for c in part):\n                    return 'Neither'\n            return 'IPv6'\n        if IP.count('.') == 3:\n            return validateIPv4(IP)\n        elif IP.count(':') == 7:\n            return validateIPv6(IP)\n        else:\n            return 'Neither'","hash":"592e7d7810528733b1f3dfb64cab1d12432893df8ae77cc26e0ddc446df957d4","origins":[{"source":"solutions","path":"Validate IP Address.py"}]}],"sources":["solutions"]},"topic-verifypreorderserializationofabinarytree":{"key":"topic-verifypreorderserializationofabinarytree","number":null,"title":"Verify Preorder Serialization of a Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Verify Preorder Serialization of a Binary Tree.py","code":"class Solution:\n    def isValidSerialization(self, preorder: str) -> bool:\n        nodes = preorder.split(',')\n        slots = 1\n        for node in nodes:\n            if slots <= 0:\n                return False\n            slots += -1 if node == '#' else 1\n        return slots == 0","hash":"80ae103b1dcbd396510a5c678e5d429cce1408af98be0c142ec0e7fb1002492e","origins":[{"source":"solutions","path":"Verify Preorder Serialization of a Binary Tree.py"}]}],"sources":["solutions"]},"topic-verifyinganaliendictionary":{"key":"topic-verifyinganaliendictionary","number":null,"title":"Verifying an Alien Dictionary","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Verifying an Alien Dictionary.py","code":"class Solution:\n    def isAlienSorted(self, words: List[str], order: str) -> bool:\n        orderMap = defaultdict(int)\n        for index, char in enumerate(order, start = 1):\n            orderMap[char] = index\n        for i in range(len(words) - 1):\n            word1 = words[i]\n            word2 = words[i + 1]\n            for j in range(min(len(word1), len(word2))):\n                if word1[j] != word2[j]:\n                    if orderMap[word1[j]] > orderMap[word2[j]]:\n                        return False\n                    break\n            else:\n                if len(word1) > len(word2):\n                    return False\n        return True","hash":"0a0dd7e03fd94faf6466dc3660805611b8c5138bc99f31419e57d4ef285ee5d0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Verifying an Alien Dictionary.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-02 Leetcoding Challenge/Verifying an Alien Dictionary.py"},{"source":"solutions","path":"Verifying an Alien Dictionary.py"}]}],"sources":["solutions"]},"topic-verticalordertraversalofabinarytreebfsapproachwithglobalsorting":{"key":"topic-verticalordertraversalofabinarytreebfsapproachwithglobalsorting","number":null,"title":"Vertical Order Traversal of a Binary Tree BFS Approach with Global Sorting","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Vertical Order Traversal of a Binary Tree - BFS Approach with Global Sorting.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def verticalTraversal(self, root: TreeNode) -> List[List[int]]:\n        nodesList = []\n        \n        def BFS(root):\n            queue = deque([(root, 0, 0)])\n            while len(queue) != 0:\n                node, row, column = queue.popleft()\n                if node is not None:\n                    nodesList.append([column, row, node.val])\n                    queue.append((node.left, row+1, column-1))\n                    queue.append((node.right, row+1, column+1))\n        \n        BFS(root)\n        \n        nodesList.sort()\n        \n        d = OrderedDict()\n        for column, row, val in nodesList:\n            if column in d:\n                d[column].append(val)\n            else:\n                d[column] = [val]\n        return d.values()","hash":"7791195c05f9c06e87f2119988092ba9cb61923f2f6fa97c623913a76c741ca8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Vertical Order Traversal of a Binary Tree - BFS Approach with Global Sorting.py"}]}],"sources":["solutions"]},"topic-verticalordertraversalofabinarytreebfsapproachwithpartitionsorting":{"key":"topic-verticalordertraversalofabinarytreebfsapproachwithpartitionsorting","number":null,"title":"Vertical Order Traversal of a Binary Tree BFS Approach with Partition Sorting","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Vertical Order Traversal of a Binary Tree - BFS Approach with Partition Sorting.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def verticalTraversal(self, root: TreeNode) -> List[List[int]]:\n        if root is None:\n            return []\n        columnTable = defaultdict(list)\n        minColumn = maxColumn = 0\n        \n        def BFS(root):\n            queue = deque([(root, 0, 0)])\n            nonlocal minColumn, maxColumn\n            while len(queue) > 0:\n                node, row, column = queue.popleft()\n                if node is not None:\n                    columnTable[column].append((row, node.val))\n                    minColumn = min(minColumn, column)\n                    maxColumn = max(maxColumn, column)\n                    queue.append((node.left, row+1, column-1))\n                    queue.append((node.right, row+1, column+1))\n        \n        BFS(root)\n        result = []\n        for col in range(minColumn, maxColumn + 1):\n            result.append([val for row, val in sorted(columnTable[col])])\n        return result","hash":"55f6c27837a14ff7cc81904f14e362a10018cd9faf858f2249afe8255c136c42","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Vertical Order Traversal of a Binary Tree - BFS Approach with Partition Sorting.py"}]}],"sources":["solutions"]},"topic-videostitching":{"key":"topic-videostitching","number":null,"title":"Video Stitching","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Video Stitching.py","code":"class Solution:\n    def videoStitching(self, clips: List[List[int]], time: int) -> int:\n        clips.sort(key = lambda x: (x[0], -x[1]))\n        if clips[0][0] > 0:\n            return -1\n        heap, index, count = [(-clips[0][1], clips[0][0]),], 1, 0\n        while heap:\n            end, start = heapq.heappop(heap)\n            end *= -1\n            count += 1\n            if end >= time:\n                return count\n            for s, e in clips[index:]:\n                if start <= s <= end:\n                    heapq.heappush(heap, (-e, s))\n                    index += 1\n                else:\n                    break\n        return -1","hash":"abe27ae527dee6a3e444a8b705df07efa1af0f0e5c2e6fb430526d7244a35279","origins":[{"source":"solutions","path":"Video Stitching.py"}]}],"sources":["solutions"]},"topic-vowelspellchecker":{"key":"topic-vowelspellchecker","number":null,"title":"Vowel Spellchecker","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Vowel Spellchecker.py","code":"class Solution:\n    def spellchecker(self, wordlist: List[str], queries: List[str]) -> List[str]:\n        perfectWords, lowerWords, devowelWords = set(wordlist), {}, {}\n        def replaceVowels(word):\n            return ''.join('*' if char in 'aeiou' else char for char in word)\n        for word in wordlist:\n            lowerWord = word.lower()\n            lowerWords.setdefault(lowerWord, word)\n            devowelWords.setdefault(replaceVowels(lowerWord), word)\n        def solve(query):\n            if query in perfectWords:\n                return query\n            lowerQuery = query.lower()\n            if lowerQuery in lowerWords:\n                return lowerWords[lowerQuery]\n            devowelQuery = replaceVowels(lowerQuery)\n            if devowelQuery in devowelWords:\n                return devowelWords[devowelQuery]\n            return ''\n        return map(solve, queries)","hash":"63495baa1e3d06afb79622a229155b4829afc9ef77b93a42166a9317a88d85d3","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Vowel Spellchecker.py"}]}],"sources":["solutions"]},"topic-webcrawler":{"key":"topic-webcrawler","number":null,"title":"Web Crawler","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Web Crawler.py","code":"# \"\"\"\n# This is HtmlParser's API interface.\n# You should not implement it, or speculate about its implementation\n# \"\"\"\n#class HtmlParser(object):\n#    def getUrls(self, url):\n#        \"\"\"\n#        :type url: str\n#        :rtype List[str]\n#        \"\"\"\n\nclass Solution:\n    def crawl(self, startUrl: str, htmlParser: 'HtmlParser') -> List[str]:\n        urls = set()\n        def dfs(url):\n            if url not in urls:\n                urls.add(url)\n                hostName = re.split('://|/', url)[1]\n                newUrls = htmlParser.getUrls(url)\n                for newUrl in newUrls:\n                    if re.split('://|/', newUrl)[1] == hostName:\n                        dfs(newUrl)\n        dfs(startUrl)\n        return list(urls)","hash":"71e2f69f6bf8c98b2e294278dbf26805999d2c547892d136173fd10905be066c","origins":[{"source":"solutions","path":"Web Crawler.py"}]}],"sources":["solutions"]},"topic-webcrawlermultithreaded":{"key":"topic-webcrawlermultithreaded","number":null,"title":"Web Crawler Multithreaded","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Web Crawler Multithreaded.py","code":"# \"\"\"\n# This is HtmlParser's API interface.\n# You should not implement it, or speculate about its implementation\n# \"\"\"\n#class HtmlParser(object):\n#    def getUrls(self, url):\n#        \"\"\"\n#        :type url: str\n#        :rtype List[str]\n#        \"\"\"\ndef getHostName(url: str) -> str:\n    return url.split('/')[2:3]\n\nfrom threading import Thread\n\nclass URLFetch(Thread):\n    def __init__(self, url: str, hostName: str, htmlParser: 'HtmlParser'):\n        Thread.__init__(self)\n        self.url = url\n        self.hostName = hostName\n        self.htmlParser = htmlParser\n        self.urls = set()\n        \n    def run(self):\n        self.urls = set([u for u in self.htmlParser.getUrls(self.url) if getHostName(u) == self.hostName])\n\nclass Solution:\n    def crawl(self, startUrl: str, htmlParser: 'HtmlParser') -> List[str]:\n        hostName = getHostName(startUrl)\n        queue, visited = [startUrl], set([startUrl])\n        while queue:\n            nextUrls = set()\n            threads = [URLFetch(url, hostName, htmlParser) for url in queue]\n            for thread in threads:\n                thread.start()\n            for thread in threads:\n                thread.join()\n                nextUrls |= thread.urls\n            nextUrls -= visited\n            visited |= nextUrls\n            queue = nextUrls\n        return visited","hash":"218ca489b5ca6498c6cfad27b129535291f8f63b80b21c9d2a76d2d7124f1fb9","origins":[{"source":"solutions","path":"Web Crawler Multithreaded.py"}]}],"sources":["solutions"]},"topic-widestverticalareabetweentwopointscontainingnopoints":{"key":"topic-widestverticalareabetweentwopointscontainingnopoints","number":null,"title":"Widest Vertical Area Between Two Points Containing No Points","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Widest Vertical Area Between Two Points Containing No Points.py","code":"class Solution:\n    def maxWidthOfVerticalArea(self, points: List[List[int]]) -> int:\n        points.sort()\n        maxDiff = float('-inf')\n        for i in range(1, len(points)):\n            maxDiff = max(maxDiff, points[i][0] - points[i - 1][0])\n        return maxDiff","hash":"0100bcbc0e6d741c9b60174a89852074d78b0914182a3397f7102b7a7f3cace4","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 38/Widest Vertical Area Between Two Points Containing No Points.py"}]}],"sources":["solutions"]},"topic-wigglesortii":{"key":"topic-wigglesortii","number":null,"title":"Wiggle Sort II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Wiggle Sort II.py","code":"class Solution:\n    def wiggleSort(self, nums: List[int]) -> None:\n        \"\"\"\n        Do not return anything, modify nums in-place instead.\n        \"\"\"\n        from sortedcontainers import SortedDict\n        count, size = SortedDict(Counter(nums)), len(nums)\n        i = size - 2 if size % 2 == 0 else size - 1\n        for key, value in count.items():\n            for j in range(value):\n                nums[i] = key\n                i -= 2\n                if i < 0:\n                    i = size - 2 if size % 2 != 0 else size - 1","hash":"751c1f6d546b8bde5efe316825780f4a83922ae67eaa60beac2aecd87e8a0984","origins":[{"source":"solutions","path":"Wiggle Sort II.py"}]}],"sources":["solutions"]},"topic-wordpattern":{"key":"topic-wordpattern","number":null,"title":"Word Pattern","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Word Pattern.py","code":"class Solution:\n    def wordPattern(self, pattern: str, s: str) -> bool:\n        words = s.split(' ')\n        patternMap, wordMap = {}, {}\n        if len(pattern) != len(words):\n            return False\n        for index, char in enumerate(pattern):\n            if char in patternMap:\n                if patternMap[char] != words[index]:\n                    return False\n            else:\n                if words[index] in wordMap:\n                    return False\n                else:\n                    patternMap[char] = words[index]\n                    wordMap[words[index]] = char\n        return True","hash":"45a5bc6b030ea46a83f3d84702bff216e08267040b3d049af378dc41f2ac27f1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Word Pattern.py"}]},{"language":"python","name":"Word Pattern.py","code":"class Solution:\n    def wordPattern(self, pattern: str, s: str) -> bool:\n        characterMap = {}\n        wordList = s.split(' ')\n        patternLength = len(pattern)\n        wordsLength = len(wordList)\n        if patternLength != wordsLength:\n            return False\n        for i, p in enumerate(pattern):\n            if p not in characterMap:\n                if wordList[i] in characterMap.values():\n                    return False\n                else:\n                    characterMap[p] = wordList[i]\n            else:\n                if characterMap[p] != wordList[i]:\n                    return False\n        return True","hash":"1473f2008458a0358490b64a0842a5db2c71971052cc6bc71474ebdec8d054b9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Word Pattern.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Word Pattern.py"},{"source":"solutions","path":"Word Pattern.py"}]}],"sources":["solutions"]},"topic-xofakindinadeckofcards":{"key":"topic-xofakindinadeckofcards","number":null,"title":"X of a Kind in a Deck of Cards","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"X of a Kind in a Deck of Cards.py","code":"class Solution:\n    def hasGroupsSizeX(self, deck: List[int]) -> bool:\n        if len(deck) < 2:\n            return False\n        counter = Counter(deck)\n        from fractions import gcd\n        X = min(counter.values())\n        for val in counter.values():\n            X = gcd(X, val)\n        if X < 2:\n            return False\n        for card, freq in counter.items():\n            if freq % X != 0:\n                return False\n        return True","hash":"406334f12621e362b4d6256b50d49b085be3f8ab7f420bf44f2cc360e22e8c03","origins":[{"source":"solutions","path":"X of a Kind in a Deck of Cards.py"}]}],"sources":["solutions"]},"topic-xoroperationinanarray":{"key":"topic-xoroperationinanarray","number":null,"title":"XOR Operation in an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"XOR Operation in an Array.py","code":"class Solution:\n    def xorOperation(self, n: int, start: int) -> int:\n        result = 0\n        for index in range(n):\n            result ^= (start + 2 * index)\n        return result","hash":"3e3cf15552581aafab4e6ce205900e0a9d7912dcf1fff22dc583954d04ae9e99","origins":[{"source":"solutions","path":"XOR Operation in an Array.py"}]}],"sources":["solutions"]}});
